mapper.select:
SELECT EXISTS (SELECT 1
               FROM travel_plan_final_members m
                        JOIN travel_plan_final_snapshots s ON s.id = m.snapshot_id
               WHERE s.travel_plan_id = #{travelPlanId}
                 AND m.user_id = #{userId}
                 AND m.hidden_at IS NULL)

mapper.update:
UPDATE travel_plan_final_members m
    JOIN travel_plan_final_snapshots s ON s.id = m.snapshot_id
SET m.hidden_at = CURRENT_TIMESTAMP
WHERE s.travel_plan_id = #{travelPlanId}
  AND m.user_id = #{userId}
  AND m.hidden_at IS NULL
